def hydrate_time(nanoseconds, tz=None):
    """Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds: number of nanoseconds since midnight
    :param tz: optional timezone (datetime.tzinfo)
    :return: datetime.time
    """
    if nanoseconds is None:
        return None
    ns_per_second = 1_000_000_000
    total_seconds = nanoseconds // ns_per_second
    remaining_ns = nanoseconds % ns_per_second
    microseconds = remaining_ns // 1_000
    seconds = total_seconds % 60
    minutes = (total_seconds // 60) % 60
    hours = (total_seconds // 3600) % 24
    if tz is not None:
        dt = datetime.datetime(1970, 1, 1, hours, minutes, seconds, microseconds, tzinfo=tz)
        return dt.time()
    else:
        return datetime.time(hours, minutes, seconds, microseconds)

