        return list(self._items.values())

    # Prepare a list of all values for index-based access
    all_values = list(self._items.values())

    result = []
    for k in keys:
        if isinstance(k, int):
            # Index-based lookup
            try:
                result.append(all_values[k])
            except IndexError:
