def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.
    """
    if maxsize is None or maxsize <= 0:
        # No caching
        def decorator(func):
            return func
        return decorator

    def _make_key(args, kwargs, typed):
        if typed:
            key = tuple((a, type(a)) for a in args)
            if kwargs:
                kw = tuple(sorted((k, v, type(v)) for k, v in kwargs.items()))
            else:
                kw = None
        else:
            key = args
            if kwargs:
                kw = tuple(sorted(kwargs.items()))
            else:
                kw = None
        return (key, kw)

    def decorator(func):
        cache = {}
        counts = {}

        def wrapper(*args, **kwargs):
            key = _make_key(args, kwargs, typed)
            if key in cache:
                counts[key] += 1
                return cache[key]
            # compute result
            result = func(*args, **kwargs)
            # store in cache
            cache[key] = result
            counts[key] = 1
            # evict if necessary
            if len(cache) > maxsize:
                # find key with lowest count
                min_count = min(counts.values())
                # choose one key with min_count
                for k in list(counts):
                    if counts[k] == min_count:
                        del cache[k]
                        del counts[k]
