def to_csv(self, separator=",", header=None):
    """.. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
          Iterables are converted to tables.

    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.

    To convert :class:`Graph` to CSV inside a Lena sequence,
    use :class:`lena.output.ToCSV`.
    """
    lines = []
    if header is not None:
        lines.append(header)
    for point in self.points():
        # Expect point to be a tuple (coord, value)
        if isinstance(point, tuple) and len(point) == 2:
            coord, value = point
        else:
            try:
                coord, value = point[0], point[1]
            except Exception:
                continue
        # Convert coordinate
        if isinstance(coord, (list, tuple)):
            coord_str = separator.join(str(c) for c in coord)
        else:
            coord_str = str(coord)
        # Convert value
        if isinstance(value, (list, tuple, set)):
            value_strs = [str(v) for v in value]
        elif isinstance(value, dict):
            value_strs = [str(v) for v in value.values()]
        else:
            value_strs = [str(value)]
        line = separator.join([coord_str] + value_strs)
        lines.append(line)
    return "\n".join(lines)

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Attempt to retrieve the error array from self.Data if available
    err = None
    if hasattr(self, "Data") and isinstance(self.Data, dict):
        if coord_name in self.Data and isinstance(self.Data[coord_name], dict):
            err = self.Data[coord_name].get("err")
    # Fallback to a dedicated errors dictionary
    if err is None and hasattr(self, "errors"):
        err = self.errors.get(coord_name)
    # If no error information is found, return an empty array
    if err is None:
        return np.array([], dtype=int)
    err_arr = np.asarray(err)
    # Build a mask of valid error entries (not NaN and not None)
    try:
        mask = ~np.isnan(err_arr)
    except TypeError:
        mask = err_arr != None
    return np.where(mask)[0]

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # Direct instance of FillRequest
    if isinstance(seq, FillRequest):
        return True
    # Reject if seq itself is a Source sequence
    if isinstance(seq, Source):
        return False
    # Try iterating over seq to find a FillRequest element
    try:
        for item in seq:
            if isinstance(item, FillRequest):
                return True
    except TypeError:
        # seq is not iterable
        return False
    return False

