def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    errors = []

    # Regular expressions for keys and values. These should be defined elsewhere
    # in the module. For the purpose of this function we assume they exist.
    try:
        key_regex = LABEL_KEY_REGEX
        value_regex = LABEL_VALUE_REGEX
    except NameError:
        # If the regexes are not defined, we cannot perform validation.
        # Raise an informative error.
        raise ValidationError(
            ["Regular expression patterns for label keys and values are not defined."]
        )

    for key, value in labels.items():
        # Validate key
        if not isinstance(key, (str, bytes)):
            errors.append({str(key): "expected string or bytes-like object"})
        else:
            key_str = key.decode() if isinstance(key, bytes) else key
            if not key_regex.match(key_str):
                errors.append(
                    {key_str: f"Label key '{key_str}' does not match the regex [...]"}
                )

        # Validate value
        if isinstance(value, (str, bytes)):
            value_str = value.decode() if isinstance(value, bytes) else value
            if not value_regex.match(value_str):
                errors.append(
                    {value_str: f"Label value '{value_str}' does not match the regex [...]"}
                )
        else:
            # For non-string values (including lists, dicts, etc.)
            errors.append({str(value): "expected string or bytes-like object"})

    if errors:
        raise ValidationError(errors)

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.
    """
    # Identify fields that should be copied verbatim when at the top level
    identifying_fields = {"apiVersion", "kind", "metadata"}

    result = {}

    # Copy identifying fields verbatim if this is the top level
    if first_level:
        for key in identifying_fields:
            if key in manifest_dict:
                result[key] = manifest_dict[key]

    for key, value in manifest_dict.items():
        # Skip reprocessing identifying fields at the top level
        if first_level and key in identifying_fields:
            continue

        if isinstance(value, dict):
            # Recurse into nested dictionaries
            result[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, list):
            # Preserve list structure, but replace primitives with None
            new_list = []
            for item in value:
                if isinstance(item, dict):
                    new_list.append(generate_default_observer_schema_dict(item, first_level=False))
                else:
                    new_list.append(None)
            result[key] = new_list
        else:
            # Replace all other values with None
            result[key] = None

    return result

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Ensure the observer_schema attribute exists and is a dict
    if not hasattr(app.spec, "observer_schema") or app.spec.observer_schema is None:
        app.spec.observer_schema = {}
    # Iterate over all resources in the manifest
    for resource in app.spec.manifest:
        kind = resource.get("kind")
        if not kind:
            continue  # skip resources without a kind
        # Build a unique key for the resource (kind + name if available)
        name = resource.get("metadata", {}).get("name")
        key = f"{kind}/{name}" if name else kind
        # Skip if a custom observer schema already exists for this key
        if key in app.spec.observer_schema:
            continue
        # Construct a minimal default observer schema
        default_schema = {
            "kind": kind,
            "apiVersion": resource.get("apiVersion"),
            "metadata": {
                "name": name,
                "namespace": resource.get("metadata", {}).get("namespace"),
            },
        }
        # Store the default schema
        app.spec.observer_schema[key] = default_schema

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        if not path:
            return False

        # Resolve pyfs root if necessary
        if hasattr(path, 'path'):
            p = getattr(path, 'path')
        else:
            p = path

        if not os.path.isdir(p):
            return False

        # Check for required OCFL metadata file
        version_file = os.path.join(p, '.ocfl_version')
        if not os.path.isfile(version_file):
            return False

        # Read and validate the version string
        with open(version_file, 'r') as vf:
            version = vf.read().strip()
        if not version or not re.match(r'^\d+\.\d+$', version):
            return False

        # Optional: validate .ocfl_root if present
        root_file = os.path.join(p, '.ocfl_root')
        if os.path.isfile(root_file):
            with open(root_file, 'r') as rf:
                root_path = rf.read().strip()
            if not root_path:
                return False

        return True
    except Exception:
        return False

