    else:
        # Assume iterable of (file, digest) tuples
        items = manifest_files

    missing = []
    for file, digest in items:
        if digest not in digests_used:
            missing.append((file, digest))

    if missing:
        missing_str = ", ".join(f"{f}:{d}" for f, d in missing)
        raise ValueError(f"Missing digests for files: {missing_str}")

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")
    if 'files' not in fixity:
        raise ValueError("Fixity block missing required 'files' key")
    files = fixity['files']
    if not isinstance(files, list):
        raise ValueError("'files' entry must be a list")
    for entry in files:
        if not isinstance(entry, dict):
            raise ValueError("Each entry in 'files' must be a dictionary")
        if 'path' not in entry:
            raise ValueError("Fixity entry missing 'path' key")
        path = entry['path']
        if path not in manifest_files:
            raise ValueError(f"Fixity references unknown file: {path}")
        if 'hash' not in entry:
            raise ValueError(f"Fixity entry for {path} missing 'hash' key")
        if not isinstance(entry['hash'], str):
            raise ValueError(f"Hash for {path} must be a string")
    return True

