def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    # Helper to recursively walk the hierarchy
    def _walk(node):
        nonlocal num_objects, good_objects
        if node is None:
            return
        num_objects += 1
        is_valid = True

        if validate_objects:
            try:
                # Assume each node has a validate() method
                node.validate()
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f"Validation failed for {node}: {exc}")

        if check_digests and hasattr(node, "check_digest"):
            try:
                node.check_digest()
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f"Digest check failed for {node}: {exc}")

        if is_valid:
            good_objects += 1

        # Recurse into children if present
        children = getattr(node, "children", [])
        for child in children:
            _walk(child)

    # Start traversal from the root of the hierarchy
    root = getattr(self, "_root", None)
    if root is None:
        raise AttributeError("Hierarchy root not defined on this instance.")
    _walk(root)

    return num_objects, good_objects

