def parse_arguments(*unparsed_arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    '''
    parser = argparse.ArgumentParser()
    # Subparsers are expected to be added elsewhere; we just create the container.
    subparsers = parser.add_subparsers(dest='subparser_name')
    # Parse the provided arguments, allowing unknown arguments to be ignored.
    namespace, _ = parser.parse_known_args(list(unparsed_arguments))
    # Determine which subparser (if any) was used.
    subparser_name = getattr(namespace, 'subparser_name', None)
    if subparser_name:
        return {subparser_name: namespace}
    else:
        return {'global': namespace}

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        for key, value in d.items():
            result[key] = result.get(key, 0) + value
    return result

