def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    seen = set()
    stack = [cls]
    while stack:
        parent = stack.pop()
        for child in parent.__subclasses__():
            if child not in seen:
                seen.add(child)
                stack.append(child)
    return seen

