def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import os
    import subprocess

    # Determine the extraction directory name
    if filename:
        extract_dir_name = filename
    else:
        base_name = os.path.basename(archive_path)
        # Strip common archive extensions
        if base_name.endswith(".tar.gz"):
            extract_dir_name = base_name[:-7]
        elif base_name.endswith(".tgz"):
            extract_dir_name = base_name[:-4]
        elif base_name.endswith(".tar.bz2"):
            extract_dir_name = base_name[:-8]
        elif base_name.endswith(".tbz2"):
            extract_dir_name = base_name[:-5]
        elif base_name.endswith(".zip"):
            extract_dir_name = base_name[:-4]
        elif base_name.endswith(".tar"):
            extract_dir_name = base_name[:-4]
        else:
            extract_dir_name = base_name

    # Build the full extraction path
    extract_dir = os.path.join(tmp_path, extract_dir_name)

    # Ensure the extraction directory does not already exist
    if os.path.exists(extract_dir):
        raise FileExistsError(f"Extraction directory {extract_dir} already exists")

    os.makedirs(extract_dir, exist_ok=True)

    # Determine extraction command based on archive type
    if archive_path.endswith(".tar.gz") or archive_path.endswith(".tgz"):
        cmd = ["tar", "-xzf", archive_path, "-C", extract_dir]
    elif archive_path.endswith(".tar.bz2") or archive_path.endswith(".tbz2"):
        cmd = ["tar", "-xjf", archive_path, "-C", extract_dir]
    elif archive_path.endswith(".tar"):
        cmd = ["tar", "-xf", archive_path, "-C", extract_dir]
    elif archive_path.endswith(".zip"):
        cmd = ["unzip", "-q", archive_path, "-d", extract_dir]
    else:
        raise ValueError(f"Unsupported archive type for {archive_path}")

    # Execute the extraction
    subprocess.run(cmd, check=True)

    # Return a file:// URL pointing to the extracted repository
    abs_path = os.path.abspath(extract_dir)
    return f"file://{abs_path}"

def addignored(ignored):
