def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None:
        return None
    if isinstance(frequency, str) and frequency.strip().lower() == "always":
        return None
    if not isinstance(frequency, str):
        raise ValueError("Frequency must be a string, None, or 'always'")
    freq = frequency.strip()
    import re
    m = re.match(r'^(\d+)\s*([a-zA-Z]+)$', freq)
    if not m:
        raise ValueError(f"Cannot parse frequency: {frequency}")
    num = int(m.group(1))
    unit = m.group(2).lower()
    unit_map = {
        'day': 'days', 'days': 'days',
        'week': 'weeks', 'weeks': 'weeks',
        'hour': 'hours', 'hours': 'hours',
        'minute': 'minutes', 'minutes': 'minutes',
        'second': 'seconds', 'seconds': 'seconds',
        'millisecond': 'milliseconds', 'milliseconds': 'milliseconds',
        'microsecond': 'microseconds', 'microseconds': 'microseconds',
    }
    if unit in unit_map:
        kwargs = {unit_map[unit]: num}
        return datetime.timedelta(**kwargs)
    elif unit in ('month', 'months'):
        return datetime.timedelta(days=num * 30)
    elif unit in ('year', 'years'):
        return datetime.timedelta(days=num * 365)
    else:
        raise ValueError(f"Unknown time unit: {unit}")

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False

    # Direct string checks for common localhost representations
    if host in ("localhost", "127.0.0.1", "::1"):
        return True

    # If host is already an IP address, check it directly
    try:
        # Try to parse as IPv4
        socket.inet_aton(host)
        return host == "127.0.0.1"
    except OSError:
        try:
            # Try to parse as IPv6
            socket.inet_pton(socket.AF_INET6, host)
            return host == "::1"
        except OSError:
            pass  # Not a plain IP string, fall back to resolution

    # Resolve the host and check if any resolved address is a loopback
    try:
        infos = socket.getaddrinfo(host, None)
    except socket.gaierror:
        return False

    for info in infos:
        addr = info[4][0]
        if addr == "127.0.0.1" or addr == "::1":
            return True

    return False

