def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # If seq is already a sequence type, return it unchanged
    if isinstance(seq, (list, tuple)):
        return seq, 'list'
    if isinstance(seq, (str, bytes, bytearray)):
        return seq, 'string'
    # If seq has a read method, read from it
    if hasattr(seq, 'read'):
        if bufsize is None:
            seq = seq.read()
        else:
            seq = seq.read(bufsize)
        return seq, 'string'
    # Otherwise, try to convert to a list (e.g., iterator)
    try:
        seq = list(seq)
        return seq, 'list'
    except TypeError:
        # seq is not iterable; return as is with type 'unknown'
        return seq, 'unknown'

