def get_nodeinfo_well_known_document(url, document_path=None):
    """
    Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    base_url = url.rstrip('/')
    if document_path:
        href = base_url + (document_path if document_path.startswith('/') else '/' + document_path)
    else:
        href = base_url + "/.well-known/nodeinfo/1.0.json"
    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/1.0",
                "href": href
            }
        ]
    }

def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    try:
        from lxml import etree
        import xmlsec
    except Exception:
        # Required libraries are not available
        return False

    # Parse the XML document
    try:
        root = etree.fromstring(doc)
    except Exception:
        return False

    # Find the Signature element (XMLDSig namespace)
    ns = {'ds': 'http://www.w3.org/2000/09/xmldsig#'}
    sig_elem = root.find('.//ds:Signature', namespaces=ns)
    if sig_elem is None:
        return False

    # Load the public key (PEM format)
    try:
        key = xmlsec.Key.from_memory(public_key, xmlsec.KeyFormat.PEM, None)
    except Exception:
        return False

    # Create a signature context and verify
    ctx = xmlsec.SignatureContext()
    ctx.key = key
    try:
        ctx.verify(sig_elem)
        return True
    except xmlsec.VerificationError:
        return False
    except Exception:
        return False

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not document:
        return None
    # Try JSON first
    try:
        data = json.loads(document)
        # Ensure it has the expected structure
        if isinstance(data, dict):
            return data
    except Exception:
        pass
    # Fallback to XRD (XML)
    try:
        root = ET.fromstring(document)
        # XRD root may have namespace; strip it
        def strip_ns(tag):
            return tag.split("}")[-1] if "}" in tag else tag
        result = {}
        # Subject
        subject_el = root.find(".//{*}Subject")
        if subject_el is not None:
            result["subject"] = subject_el.text
        # Links
        links = []
        for link_el in root.findall(".//{*}Link"):
            link = {}
            for attr in ["rel", "href", "type", "title", "template"]:
                if attr in link_el.attrib:
                    link[attr] = link_el.attrib[attr]
            # Some XRD may have <Rel> child elements
            for rel_el in link_el.findall(".//{*}Rel"):
                if rel_el.text:
                    link.setdefault("rel", []).append(rel_el.text)
            links.append(link)
        if links:
            result["links"] = links
        return result
    except Exception:
        return None

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """Try to retrieve an RFC7033 webfinger document. Does not raise if it fails."""
    try:
        host = handle.split("@")[1]
    except Exception:
        return None
    url = f"https://{host}/.well-known/webfinger?resource=acct:{quote(handle)}"
    try:
        with closing(urllib2.urlopen(url)) as page:
            return page.read().decode("utf-8")
    except Exception:
        return None

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    try:
        host = handle.split("@")[1]
    except AttributeError:
        logger.warning("retrieve_and_parse_diaspora_webfinger: invalid handle given: %s", handle)
        return None
    document, code, exception = fetch_document(
        host=host, path="/.well-known/webfinger?resource=acct:%s" % quote(handle),
    )
    if document:
        return parse_diaspora_webfinger(document)
    hostmeta = retrieve_diaspora_host_meta(host)
    if not hostmeta:
        return None
    url = hostmeta.find_link(rels="lrdd").template.replace("{uri}", quote(handle))
    document, code, exception = fetch_document(url)
    if exception:
        return None
    return parse_diaspora_webfinger(document)

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    import os
    import fnmatch
    file_list = []
    for directory in settings_dirs:
        try:
            for fname in os.listdir(directory):
                if fnmatch.fnmatch(fname, spec_option):
                    file_list.append(os.path.join(directory, fname))
        except OSError:
            continue
    return sorted(file_list)

