def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    if spec_content is None:
        raise IRValidatorException("spec_content must be provided")
    try:
        data = yaml.safe_load(spec_content)
    except Exception as e:
        raise IRValidatorException(f"Error parsing YAML: {e}")
    if not isinstance(data, dict):
        raise IRValidatorException("Spec content must be a YAML mapping")
    required = getattr(cls, 'REQUIRED_FIELDS', [])
    missing = [field for field in required if field not in data]
    if missing:
        raise IRValidatorException(f"Missing required fields: {', '.join(missing)}")
    return data

@classmethod
    def validate_from_file(cls, yaml_file=None):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        if yaml_file is None:
            raise IRValidatorException("yaml_file argument must be supplied")

        try:
            with open(yaml_file, 'r') as f:
                data = yaml.load(f, Loader=Loader)
        except Exception as e:
            raise IRValidatorException(f"Error loading YAML file: {e}")

        required_fields = getattr(cls, "REQUIRED_FIELDS", [])
        missing = [field for field in required_fields if field not in data]
        if missing:
            raise IRValidatorException(f"Missing required fields: {', '.join(missing)}")

        return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    def _resolve(d):
        if isinstance(d, dict):
            # If this dict contains an 'include' key, replace it with the referenced parser
            if 'include' in d:
                inc_key = d.pop('include')
                if inc_key not in parser_dict:
                    raise KeyError(f"Included parser '{inc_key}' not found in parser_dict")
                # Recursively resolve the included parser dict
                inc_val = _resolve(parser_dict[inc_key])
                # Merge the included dict into the current dict
                d.update(inc_val)
            # Recursively resolve nested structures
            for key, val in list(d.items()):
                d[key] = _resolve(val)
        elif isinstance(d, list):
            return [_resolve(item) for item in d]
        return d

    # Resolve in place
    _resolve(parser_dict)

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    defaults = {}
    for arg in self.args:
        if not isinstance(arg, _BaseOpt):
            raise errors.InvalidSchemeError('Unable to resolve default for non-Option type')
        # Attempt to get a value from the spec
        value = None
        if hasattr(self, 'spec'):
            if isinstance(self.spec, dict):
                value = self.spec.get(arg.name)
            else:
                # Assume spec behaves like a mapping or has a get method
                get_method = getattr(self.spec, 'get', None)
                if callable(get_method):
                    value = get_method(arg.name)
        if value is not None:
            defaults[arg.name] = value
            continue
        # Fallback to the option's own default if it exists
        if not isinstance(arg.default, NoDefault):
            defaults[arg.name] = arg.default
        # Handle nested dictionary options
        if isinstance(arg, DictOption) and arg.scheme:
            sub_defaults = arg.scheme.get_spec_defaults()
            if sub_defaults:
                defaults[arg.name] = sub_defaults
    return defaults

