def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    import os
    norm_path = os.path.abspath(path)
    norm_root = os.path.abspath(root)

    # Handle the special case where root is the filesystem root
    if norm_root == os.sep:
        if norm_path == norm_root:
            return ''
        return norm_path.lstrip(os.sep)

    # Ensure the path actually starts with the root
    if norm_path == norm_root:
        return ''
    if not norm_path.startswith(norm_root + os.sep):
        raise ValueError(f"Path '{path}' does not start with root '{root}'.")
    # Return the relative path after the root
    return os.path.relpath(norm_path, norm_root)
